#!/usr/bin/env bash
set -euo pipefail
IFS=$'\n\t'

verbose=0; file=""
while getopts ":f:vh" opt; do
  case "$opt" in
    f) file="$OPTARG" ;;
    v) verbose=1 ;;
    h) echo "usage: $0 [-v] -f FILE"; exit 0 ;;
    \?) echo "unknown option -$OPTARG" >&2; exit 1 ;;
    :) echo "-$OPTARG needs a value" >&2; exit 1 ;;
  esac
done
shift $((OPTIND - 1))   # remaining args are in "$@"

while [[ $# -gt 0 ]]; do
  case "$1" in
    --name) name="$2"; shift 2 ;;
    --verbose) verbose=1; shift ;;
    --) shift; break ;;
    -*) echo "unknown option: $1" >&2; exit 1 ;;
    *) break ;;
  esac
done

f="/path/to/report.tar.gz"
echo "${f##*/}"    # report.tar.gz  (basename)
echo "${f%.*}"     # /path/to/report.tar (drop last extension)
echo "${f%%.*}"    # /path/to/report (drop all extensions)
echo "${#f}"       # length
s="hello"; echo "${s^^}"   # HELLO
